CREATE TABLE IF NOT EXISTS arenas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,camp_id BIGINT UNSIGNED NOT NULL,field_no SMALLINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,UNIQUE KEY camp_field(camp_id,field_no),FOREIGN KEY(camp_id) REFERENCES camps(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS score_adjustments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,camp_id BIGINT UNSIGNED NOT NULL,team_id BIGINT UNSIGNED NOT NULL,amount INT NOT NULL,reason VARCHAR(300) NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(camp_id) REFERENCES camps(id) ON DELETE CASCADE,FOREIGN KEY(team_id) REFERENCES sub_teams(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS live_displays (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,camp_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,token CHAR(64) NOT NULL UNIQUE,mode ENUM('idle','scores','matches') NOT NULL DEFAULT 'idle',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(camp_id) REFERENCES camps(id) ON DELETE CASCADE);
